-- Execute uma vez no SQL Editor do Supabase, em um projeto novo.
create table public.profiles(id uuid primary key references auth.users(id),name text not null,role text not null check(role in ('admin','client')),active boolean not null default true,created_at timestamptz not null default now());
create table public.clients(id uuid primary key references public.profiles(id),email text not null unique,phone text not null default '',created_at timestamptz not null default now());
create table public.wallets(client_id uuid primary key references public.clients(id),balance_cents bigint not null default 0 check(balance_cents>=0));
create table public.pix_settings(id boolean primary key default true check(id),pix_key text not null,receiver_name text not null,city text not null,bank text not null check(bank in ('Nubank','Next','Outro')),minimum_cents bigint not null check(minimum_cents>0),updated_at timestamptz not null default clock_timestamp());
create table public.pix_requests(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id),amount_cents bigint not null check(amount_cents>0),txid text not null unique check(txid ~ '^[A-Za-z0-9]{1,25}$'),payload text not null,receiver_name text not null,bank text not null,status text not null default 'awaiting' check(status in ('awaiting','informed','confirmed','rejected')),created_at timestamptz not null default now(),informed_at timestamptz,reviewed_at timestamptz,reviewed_by uuid references public.profiles(id));
create table public.wallet_transactions(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id),type text not null check(type in ('pix','manual_credit','manual_debit','meta_ads','refund')),amount_cents bigint not null check(amount_cents<>0),description text not null,balance_before bigint not null check(balance_before>=0),balance_after bigint not null check(balance_after>=0),actor_id uuid not null references public.profiles(id),pix_request_id uuid unique references public.pix_requests(id),operation_id uuid not null unique,occurred_on date not null default current_date,created_at timestamptz not null default now(),check(balance_after=balance_before+amount_cents),check((type in ('pix','manual_credit','refund') and amount_cents>0) or (type in ('manual_debit','meta_ads') and amount_cents<0)));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid not null references public.profiles(id),action text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create index on public.pix_requests(client_id,created_at desc);
create index on public.pix_requests(status);
create index on public.wallet_transactions(client_id,occurred_on desc);
create index on public.audit_logs(created_at desc);
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin' and active); $$;
create function public.is_active() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and active); $$;
create function public.require_admin() returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() then raise exception 'Acesso não autorizado'; end if; end $$;
alter table public.profiles enable row level security;
alter table public.clients enable row level security;
alter table public.wallets enable row level security;
alter table public.wallet_transactions enable row level security;
alter table public.pix_requests enable row level security;
alter table public.pix_settings enable row level security;
alter table public.audit_logs enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(is_admin() or (id=auth.uid() and is_active()));
create policy clients_read on public.clients for select to authenticated using(is_admin() or (id=auth.uid() and is_active()));
create policy wallets_read on public.wallets for select to authenticated using(is_admin() or (client_id=auth.uid() and is_active()));
create policy transactions_read on public.wallet_transactions for select to authenticated using(is_admin() or (client_id=auth.uid() and is_active()));
create policy requests_read on public.pix_requests for select to authenticated using(is_admin() or (client_id=auth.uid() and is_active()));
create policy settings_read on public.pix_settings for select to authenticated using(is_admin());
create policy audit_read on public.audit_logs for select to authenticated using(is_admin());
revoke all on public.profiles,public.clients,public.wallets,public.wallet_transactions,public.pix_requests,public.pix_settings,public.audit_logs from anon,authenticated;
grant select on public.profiles,public.clients,public.wallets,public.wallet_transactions,public.pix_requests,public.pix_settings,public.audit_logs to authenticated;
create function public.register_client(p_id uuid,p_name text,p_email text,p_phone text) returns void language plpgsql security definer set search_path=public as $$ begin perform require_admin(); insert into profiles(id,name,role) values(p_id,p_name,'client');insert into clients(id,email,phone) values(p_id,p_email,p_phone);insert into wallets(client_id) values(p_id);insert into audit_logs(actor_id,action,entity_id) values(auth.uid(),'client_created',p_id);end $$;
create function public.edit_client(p_id uuid,p_name text,p_phone text,p_active boolean) returns void language plpgsql security definer set search_path=public as $$ begin perform require_admin();update profiles set name=p_name,active=p_active where id=p_id and role='client';if not found then raise exception 'Cliente não encontrado';end if;update clients set phone=p_phone where id=p_id;insert into audit_logs(actor_id,action,entity_id,details) values(auth.uid(),'client_updated',p_id,jsonb_build_object('active',p_active,'name',p_name,'phone',p_phone));end $$;
create function public.log_access_reset(p_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin perform require_admin();insert into audit_logs(actor_id,action,entity_id) values(auth.uid(),'access_reset',p_id);end $$;
create function public.save_pix_settings(p_key text,p_name text,p_city text,p_bank text,p_minimum bigint) returns void language plpgsql security definer set search_path=public as $$ begin perform require_admin();if length(trim(p_key)) not between 3 and 77 or length(trim(p_name)) not between 2 and 25 or length(trim(p_city)) not between 2 and 15 then raise exception 'Configuração inválida';end if;insert into pix_settings(id,pix_key,receiver_name,city,bank,minimum_cents) values(true,p_key,p_name,p_city,p_bank,p_minimum) on conflict(id) do update set pix_key=excluded.pix_key,receiver_name=excluded.receiver_name,city=excluded.city,bank=excluded.bank,minimum_cents=excluded.minimum_cents,updated_at=clock_timestamp();insert into audit_logs(actor_id,action) values(auth.uid(),'pix_settings_updated');end $$;
create function public.create_pix_request(p_client uuid,p_cents bigint,p_txid text,p_payload text,p_receiver text,p_bank text,p_settings_version timestamptz) returns public.pix_requests language plpgsql security definer set search_path=public as $$ declare s pix_settings;r pix_requests;begin if not exists(select 1 from clients c join profiles p on p.id=c.id where c.id=p_client and p.active) then raise exception 'Acesso não autorizado';end if;select * into s from pix_settings where id=true for share;if s.id is null or s.updated_at<>p_settings_version or p_cents<s.minimum_cents or p_cents>99999999 then raise exception 'Configurações alteradas ou valor inválido. Tente novamente';end if;insert into pix_requests(client_id,amount_cents,txid,payload,receiver_name,bank) values(p_client,p_cents,p_txid,p_payload,s.receiver_name,s.bank) returning * into r;return r;end $$;
create function public.inform_payment(p_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not is_active() then raise exception 'Acesso não autorizado';end if;update pix_requests set status='informed',informed_at=now() where id=p_id and client_id=auth.uid() and status='awaiting';end $$;
create function public.review_payment(p_id uuid,p_confirm boolean) returns void language plpgsql security definer set search_path=public as $$ declare r pix_requests;before_balance bigint;begin perform require_admin();select * into r from pix_requests where id=p_id for update;if not found then raise exception 'Solicitação não encontrada';end if;if r.status in ('confirmed','rejected') then return;end if;
 if p_confirm then select balance_cents into before_balance from wallets where client_id=r.client_id for update;update wallets set balance_cents=balance_cents+r.amount_cents where client_id=r.client_id;insert into wallet_transactions(client_id,type,amount_cents,description,balance_before,balance_after,actor_id,pix_request_id,operation_id) values(r.client_id,'pix',r.amount_cents,'Recarga Pix',before_balance,before_balance+r.amount_cents,auth.uid(),r.id,r.id);end if;
 update pix_requests set status=case when p_confirm then 'confirmed' else 'rejected' end,reviewed_at=now(),reviewed_by=auth.uid() where id=p_id;insert into audit_logs(actor_id,action,entity_id) values(auth.uid(),case when p_confirm then 'pix_confirmed' else 'pix_rejected' end,p_id);end $$;
create function public.adjust_wallet(p_client uuid,p_cents bigint,p_type text,p_reason text,p_date date,p_operation uuid) returns void language plpgsql security definer set search_path=public as $$ declare b bigint;delta bigint;begin perform require_admin();if p_cents<=0 or p_cents>99999999 or p_type not in ('manual_credit','manual_debit','meta_ads','refund') or length(trim(p_reason))<3 then raise exception 'Movimentação inválida';end if;select balance_cents into b from wallets where client_id=p_client for update;if not found then raise exception 'Cliente não encontrado';end if;
 if exists(select 1 from wallet_transactions where operation_id=p_operation) then return;end if;
 delta=case when p_type in ('manual_debit','meta_ads') then -p_cents else p_cents end;if b+delta<0 then raise exception 'Saldo insuficiente';end if;update wallets set balance_cents=b+delta where client_id=p_client;insert into wallet_transactions(client_id,type,amount_cents,description,balance_before,balance_after,actor_id,operation_id,occurred_on) values(p_client,p_type,delta,p_reason,b,b+delta,auth.uid(),p_operation,p_date);insert into audit_logs(actor_id,action,entity_id,details) values(auth.uid(),'wallet_adjusted',p_client,jsonb_build_object('amount_cents',delta,'before',b,'after',b+delta,'reason',p_reason));end $$;
-- Nenhuma RPC mutadora é pública. O cliente só recebe as operações necessárias.
revoke execute on all functions in schema public from public,anon;
grant execute on function public.is_admin(),public.is_active(),public.register_client(uuid,text,text,text),public.edit_client(uuid,text,text,boolean),public.log_access_reset(uuid),public.save_pix_settings(text,text,text,text,bigint),public.inform_payment(uuid),public.review_payment(uuid,boolean),public.adjust_wallet(uuid,bigint,text,text,date,uuid) to authenticated;

grant execute on function public.create_pix_request(uuid,bigint,text,text,text,text,timestamptz) to service_role;

grant select on public.pix_settings to service_role;
